toolArgs.new_str:
@page "/"

<PageTitle>ShipmentTracker - Home</PageTitle>

<h1>Shipment Tracker</h1>

<p>Welcome to the logistics shipment tracking system.</p>

<AuthorizeView>
    <Authorized>
        <p>You are logged in as <strong>@context.User.Identity?.Name</strong>.</p>
        <p><a href="shipments">Go to Dispatcher Dashboard</a></p>
    </Authorized>
    <NotAuthorized>
        <p>Track your shipment below or <a href="Account/Login">log in</a> to access the dispatcher dashboard.</p>
    </NotAuthorized>
</AuthorizeView>

<hr />

<h2>Track a Shipment</h2>
<div class="row">
    <div class="col-md-6">
        <div class="input-group">
            <input type="text" class="form-control" placeholder="Enter tracking number" @bind="trackingNumber" @bind:event="oninput" @onkeydown="HandleKeyDown" />
            <button class="btn btn-primary" @onclick="TrackShipment">Track</button>
        </div>
    </div>
</div>

@if (isLoading)
{
    <p class="mt-3"><em>Searching...</em></p>
}
else if (searched && shipment is null)
{
    <div class="alert alert-warning mt-3">No shipment found with that tracking number.</div>
}
else if (shipment is not null)
{
    <div class="card mt-3">
        <div class="card-body">
            <h5 class="card-title">Shipment @shipment.TrackingNumber</h5>
            <table class="table">
                <tr><th>Status</th><td><span class="badge bg-@GetStatusColor(shipment.Status)">@shipment.Status</span></td></tr>
                <tr><th>Origin</th><td>@shipment.Origin</td></tr>
                <tr><th>Destination</th><td>@shipment.Destination</td></tr>
                <tr><th>Recipient</th><td>@shipment.RecipientName</td></tr>
                <tr><th>Shipped</th><td>@shipment.ShippedDate.ToString("yyyy-MM-dd")</td></tr>
                <tr><th>Estimated Delivery</th><td>@shipment.EstimatedDelivery.ToString("yyyy-MM-dd")</td></tr>
            </table>
        </div>
    </div>
}

@code {
    [Inject] private IShipmentService ShipmentService { get; set; } = default!;

    private string trackingNumber = string.Empty;
    private ShipmentDto? shipment;
    private bool searched;
    private bool isLoading;

    private async Task HandleKeyDown(KeyboardEventArgs e)
    {
        if (e.Key == "Enter")
            await TrackShipment();
    }

    private async Task TrackShipment()
    {
        if (string.IsNullOrWhiteSpace(trackingNumber)) return;
        isLoading = true;
        searched = false;
        shipment = null;
        try
        {
            shipment = await ShipmentService.GetShipmentByTrackingNumberAsync(trackingNumber.Trim());
            searched = true;
        }
        finally
        {
            isLoading = false;
        }
    }

    private static string GetStatusColor(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Delivered => "success",
        ShipmentStatus.InTransit => "info",
        ShipmentStatus.OutForDelivery => "primary",
        ShipmentStatus.Delayed => "danger",
        ShipmentStatus.Pending => "secondary",
        ShipmentStatus.PickedUp => "warning",
        _ => "secondary"
    };
}

